/**
 * Previous and next controls for a cursor-paged list (`design/components/cursor-pagination.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/cursor-pagination.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { createMemo, mergeProps, onCleanup, onMount, type JSX } from 'solid-js'

import {
  agentMember,
  claimSlot,
  createCell,
  createDerived,
  devWarning,
  elementRef,
  scope,
  watchEffect,
  type Defaults,
} from '@polymorph/solid'
import styles from '@polymorph/recipes/structure/cursor-pagination.module.css'
import Button from '../controls/Button'
import Inline from '../layout/Inline'

export interface CursorPaginationMessages {
  previous: string
  next: string
  more?: string
  end?: string
}

export interface CursorPaginationProps {
  /**
   * The app holds the pager while it does something else to the list: every control is disabled
   * and none shows busy. Not `pending`, which says the pager's own request is in flight.
   */
  disabled?: boolean
  hasNext: boolean
  /**
   * Whether the list returned a cursor that way; controlled, as cursors belong to the list. The
   * append form does not read it: it has no previous direction.
   */
  hasPrevious: boolean
  label?: string
  /**
   * Omit for the generic English defaults; localized hosts pass their own.
   */
  messages?: CursorPaginationMessages
  /**
   * `replace` (the default) swaps the window for its neighbour, so the list stays bounded.
   * `append` is "Load more": one action that adds the next window below the ones on screen, for
   * a feed or a log read from the top.
   */
  mode?: 'replace' | 'append'
  /**
   * The next window: in place of this one, or in the append form below it.
   */
  onNext: () => void
  /**
   * The previous window, in the replace form; the append form has no previous.
   */
  onPrevious?: () => void
  /**
   * The requested window has not arrived: the pressed direction shows busy and the other is
   * disabled, so a slow fetch cannot be followed by a second request.
   */
  pending?: boolean
  /**
   * The current window in the app's words, such as "26–50" or "Newest first, page 2"; never a
   * total, because the list does not return one.
   */
  position?: string
}

/** Previous and next controls for a cursor-paged list. */
export default function CursorPagination(given: CursorPaginationProps): JSX.Element {
  const props = mergeProps(
    {
      mode: 'replace',
      pending: false,
      disabled: false,
      label: 'Pagination',
      messages: (() => ({
        previous: 'Previous',
        next: 'Next',
        more: 'Load more',
        end: 'No more to load',
      }))(),
    } as Defaults<CursorPaginationProps, 'mode' | 'pending' | 'disabled' | 'label' | 'messages'>,
    claimSlot(given),
  )
  return scope(() => {
    const root = elementRef<HTMLElement>()
    const focused = createCell(null as HTMLElement | null)
    const taken = createCell(null as string | number | null)
    const asked = createCell(null as 'previous' | 'next' | null)
    const paged = createCell(false)
    const more = createDerived(() => props.messages.more ?? 'Load more')
    const end = createDerived(() => props.messages.end ?? 'No more to load')
    const ended = createDerived(() => !props.hasNext && !props.pending)
    const controls = createDerived(() =>
      props.mode === 'append'
        ? props.hasNext || props.pending
          ? ['more']
          : []
        : ['previous', 'next'],
    )
    const focusIn = createDerived(() => (event: FocusEvent) => {
      focused.value = event.target as HTMLElement
    })
    const focusOut = createDerived(() => (event: FocusEvent) => {
      if (!(event.target as HTMLElement).matches(':disabled')) focused.value = null
    })
    const keepPlace = createDerived(() => () => {
      const pager = root.value as HTMLElement | null
      if (pager === null) return
      const names: readonly (string | number)[] = controls.value
      if (!props.disabled) {
        const control = taken.value
        taken.value = null
        if (control === null || document.activeElement !== pager) return
        const button = [...pager.querySelectorAll('button')][names.indexOf(control)]
        if (button !== undefined && !button.matches(':disabled')) button.focus()
        return
      }
      const from = focused.value as HTMLElement | null
      if (from === null || !from.isConnected || !from.matches(':disabled')) return
      const active = document.activeElement
      if (active !== from && active !== null && active !== document.body) return
      taken.value =
        names[[...pager.querySelectorAll('button')].indexOf(from as HTMLButtonElement)] ?? null
      pager.focus()
    })
    const effect1 = () => {
      void (props.pending || (asked.value = null))
    }
    watchEffect(
      createMemo(() => props.pending),
      effect1,
      false,
    )
    const effect2 = () => {
      devWarning(
        props.mode !== 'append' && props.hasPrevious && !(props.onPrevious !== undefined),
        'CursorPagination: `hasPrevious` with no `onPrevious` draws a previous button that does nothing.',
      )
    }
    watchEffect(
      createMemo(
        () => props.mode !== 'append' && props.hasPrevious && !(props.onPrevious !== undefined),
      ),
      effect2,
      true,
    )
    const effect3 = () => {
      devWarning(
        props.mode === 'append' &&
          (props.messages.more === undefined || props.messages.end === undefined),
        'CursorPagination: the append form shows `messages.more` and `messages.end`; pass them with the others, so one control never mixes two languages.',
      )
    }
    watchEffect(
      createMemo(
        () =>
          props.mode === 'append' &&
          (props.messages.more === undefined || props.messages.end === undefined),
      ),
      effect3,
      true,
    )
    let release4: (() => void) | undefined
    const effect4 = () => {
      release4?.()
      const run = () => {
        keepPlace.value()
      }
      const mutation =
        typeof MutationObserver === 'undefined' ? undefined : new MutationObserver(run)
      for (const element of [root.value])
        if (element)
          mutation?.observe(element, {
            childList: true,
            characterData: true,
            subtree: true,
            attributeFilter: ['disabled'],
          })
      release4 = () => {
        mutation?.disconnect()
      }
      run()
    }
    watchEffect(
      createMemo(() =>
        props.mode === 'append'
          ? props.hasNext || props.pending || paged.value
          : props.hasPrevious || props.hasNext || props.pending,
      ),
      effect4,
      true,
    )
    onCleanup(() => release4?.())
    const effect5 = () => {
      keepPlace.value()
    }
    watchEffect(
      createMemo(() => props.disabled),
      effect5,
      false,
    )
    let release6: (() => void) | undefined
    const effect6 = () => {
      release6?.()
      const ran = agentMember({
        member: 'CursorPagination',
        element: () => root.value,
        state: () => ({
          'has-previous': props.mode !== 'append' && props.hasPrevious,
          'has-next': props.hasNext,
          position: props.position ?? '',
          pending: props.pending,
          disabled: props.disabled,
        }),
        actions: {
          previous: () =>
            (() => {
              if (props.mode === 'append')
                throw new Error('The append form has no previous window.')
              if (!props.hasPrevious) throw new Error('There is no previous window.')
              if (props.pending) throw new Error('A window is in flight; wait for it to arrive.')
              asked.value = 'previous'
              props.onPrevious?.()
            })(),
          next: () =>
            (() => {
              if (!props.hasNext) throw new Error('There is no next window.')
              if (props.pending) throw new Error('A window is in flight; wait for it to arrive.')
              asked.value = 'next'
              if (props.mode === 'append') paged.value = true
              props.onNext?.()
            })(),
        },
        withholds: () => root.value,
      })
      release6 = () => {
        ran()
      }
    }
    onMount(effect6)
    onCleanup(() => release6?.())
    return (
      <>
        {(
          props.mode === 'append'
            ? props.hasNext || props.pending || paged.value
            : props.hasPrevious || props.hasNext || props.pending
        ) ? (
          <nav
            class={styles.pagination}
            aria-label={props.label}
            aria-busy={props.pending ? true : undefined}
            data-pending={props.pending ? '' : undefined}
            data-disabled={props.disabled ? '' : undefined}
            tabindex="-1"
            data-member="cursor-pagination"
            onfocusin={($event: FocusEvent) => focusIn.value($event)}
            onfocusout={($event: FocusEvent) => focusOut.value($event)}
            ref={root.attach}
          >
            <Inline gap={2} align="center" wrap={true}>
              {props.mode === 'append' ? (
                <>
                  {props.position !== undefined ? (
                    <span class={styles.position} aria-live="polite">
                      {props.position}
                    </span>
                  ) : null}
                  {!ended.value ? (
                    <Button
                      variant="outline"
                      tone="neutral"
                      size="sm"
                      label={more.value}
                      loading={props.pending}
                      disabled={props.disabled && !props.pending}
                      onClick={() => (
                        (asked.value = 'next'),
                        (paged.value = true),
                        props.onNext?.()
                      )}
                    />
                  ) : null}
                </>
              ) : (
                <>
                  <Button
                    variant="ghost"
                    tone="neutral"
                    size="sm"
                    icon="previous"
                    label={props.messages.previous}
                    loading={props.pending && asked.value === 'previous'}
                    disabled={
                      !props.hasPrevious ||
                      (props.pending ? asked.value !== 'previous' : props.disabled)
                    }
                    onClick={() => ((asked.value = 'previous'), props.onPrevious?.())}
                  />
                  {props.position !== undefined ? (
                    <span class={styles.position} aria-live="polite">
                      {props.position}
                    </span>
                  ) : null}
                  <Button
                    variant="ghost"
                    tone="neutral"
                    size="sm"
                    trailingIcon="next"
                    label={props.messages.next}
                    loading={props.pending && asked.value === 'next'}
                    disabled={
                      !props.hasNext || (props.pending ? asked.value !== 'next' : props.disabled)
                    }
                    onClick={() => ((asked.value = 'next'), props.onNext?.())}
                  />
                </>
              )}
            </Inline>
            {props.mode === 'append' ? (
              <span class={styles.end} role="status">
                {ended.value ? end.value : null}
              </span>
            ) : null}
          </nav>
        ) : null}
      </>
    )
  })
}
